<script setup lang="ts">
import {activeAppearance,systemDark,rememberAppearance,appearanceEpoch} from '../ui/theme'
import ThemeOrnament from './ThemeOrnament.vue'
import {VERSION} from '../version'
import { ref,computed,watch,onMounted,onUnmounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { request } from '../api'
import { label,applyText } from './siteText'
import { renderMarkdown } from '../markdown'
import ArticleBody from '../reading/ArticleBody.vue'
import ArticleReader from '../reading/ArticleReader.vue'
import AdjacentPosts from '../reading/AdjacentPosts.vue'
import { colorStyle,customKeys,appearanceAttrs } from './colors'
import ArchivePage from '../discovery/ArchivePage.vue'
import LifeFeed from '../life/LifeFeed.vue'
import TripView from '../life/TripView.vue'
import PlaceMap from '../life/PlaceMap.vue'
import PhotoGallery from '../life/PhotoGallery.vue'
import TemplateRenderer from './TemplateRenderer.vue'
import PrivatePreview from '../admin/PrivatePreview.vue'
import { blankSite,navPath,fieldDisplay,type Site,type ResolvedHome as Home,type Post,type Appearance } from './types'
const props=defineProps<{embedded?:boolean;preview?:Appearance;target?:string}>();const emit=defineEmits<{(e:'navigate',path:string):void}>()
const route=useRoute(),router=useRouter(),site=ref<Site>(blankSite()),home=ref<Home|null>(null),article=ref<any>(null),section=ref<any>(null),items=ref<Post[]>([]),total=ref(0),busy=ref(false),error=ref(''),admin=ref(false),menu=ref(false),expanded=ref(''),lightbox=ref<any>(null)
const ready=ref(false)
const menuButton=ref<HTMLButtonElement|null>(null)
function closeMenu(event:KeyboardEvent){
 const trigger=menuButton.value?.getClientRects().length?menuButton.value:(event.currentTarget as HTMLElement).querySelector<HTMLButtonElement>('.nav-expand[aria-expanded=true]')
 menu.value=false;expanded.value='';trigger?.focus()
}
const neighbors=ref<any>(null)
const feed=ref<any>(null),selectedPlace=ref<string|null>(null)
function queryValue(key:string){return props.embedded?new URLSearchParams((props.target||'').split('?')[1]||'').get(key)||'':String(route.query[key]||'')}
const previewRevision=computed(()=>queryValue('revision'))
const filterYear=computed(()=>path.value.startsWith('/year-review/')?path.value.split('/').pop()||'':queryValue('year')),filterType=computed(()=>queryValue('type_id')),filterMode=computed(()=>queryValue('record_mode'))
let generation=0
const appearance=computed(()=>props.preview||activeAppearance.value),dark=computed(()=>appearance.value.mode==='dark'||appearance.value.mode==='system'&&systemDark.value)
const path=computed(()=>props.embedded?(props.target||'/').split('?')[0]!:route.path),page=computed(()=>Math.max(1,Number(props.embedded?new URLSearchParams((props.target||'').split('?')[1]||'').get('page'):route.query.page)||1))
const known=computed(()=>path.value==='/archive'||path.value==='/timeline'||/^\/year-review\/\d{1,4}$/.test(path.value)||path.value==='/'||path.value==='/sections'||path.value==='/stories'||/^\/sections\/[^/]+$/.test(path.value)||/^\/(preview\/)?posts\/[^/]+$/.test(path.value))
function activeNav(n:any){return path.value===navPath(n,site.value.sections)||n.kind==='section'&&article.value?.sections?.some((s:any)=>s.id===n.section_id)}
const roots=computed(()=>site.value.navigation.filter(n=>!n.parent_id)),children=(id:string)=>site.value.navigation.filter(n=>n.parent_id===id)
function go(url:string,event?:Event){event?.preventDefault();menu.value=false;expanded.value='';lightbox.value=null;if(props.embedded)emit('navigate',url);else void router.push(url).then(()=>{if(url.startsWith('/posts/'))window.scrollTo({top:0,behavior:'auto'})})}
function post(id:string,event?:Event){go('/posts/'+id,event)}
async function load(){const g=++generation,current=path.value,currentPage=page.value;busy.value=true;error.value='';article.value=null;section.value=null;home.value=null;feed.value=null;selectedPlace.value=null;items.value=[];neighbors.value=null;try{
 const appearanceGeneration=appearanceEpoch()
 const result=await request('/blog/site') as Site
 let isAdmin=false
 if(!props.embedded)try{const a=await request('/admin/status');isAdmin=a.is_admin===true&&a.features.dynamic_blog===true}catch{}
 let nextHome:Home|null=null,nextArticle:any=null,nextSection:any=null,nextItems:Post[]=[],nextTotal=0,data:any
 if(current==='/timeline'||current.startsWith('/year-review/')){const params=new URLSearchParams({page:String(currentPage)});if(filterType.value)params.set('type_id',filterType.value);if(filterMode.value)params.set('record_mode',filterMode.value);if(current==='/timeline'&&filterYear.value)params.set('year',filterYear.value);data=await request((current==='/timeline'?'/blog/timeline':'/blog/year-review/'+filterYear.value)+'?'+params);if(g===generation)feed.value=data}
 else if(current==='/')nextHome=await request('/blog/home') as Home
 else if(current.startsWith('/preview/posts/'))nextArticle=await request('/admin/blog/preview/'+current.split('/').pop()+(previewRevision.value?'?expected_revision='+encodeURIComponent(previewRevision.value):''))
 else if(current.startsWith('/posts/'))nextArticle=await request('/blog/records/'+current.split('/').pop())
 else if(current.startsWith('/sections/')){data=await request('/blog/sections/'+encodeURIComponent(current.split('/').pop()||'')+'?page='+currentPage);nextSection=data.section;nextItems=data.items;nextTotal=data.total}
 else if(current==='/stories'){data=await request('/blog/records?page='+currentPage);nextItems=data.items;nextTotal=data.total}
 if(g!==generation)return
 site.value=result;if(!props.embedded)rememberAppearance(result.appearance,appearanceGeneration);if((result as any).text)applyText((result as any).text);admin.value=isAdmin;home.value=nextHome;article.value=nextArticle;section.value=nextSection;items.value=nextItems;total.value=nextTotal
 if(nextArticle&&current.startsWith('/posts/')&&!props.embedded)void request('/blog/records/'+nextArticle.id+'/neighbors').then(adjacent=>{if(g===generation)neighbors.value=adjacent}).catch(()=>{/* Optional navigation cannot block reading. */})
 }catch(e:any){if(g===generation)error.value=e.status===404||e.status===422?'内容暂不可用，可能已停用、删除或尚未发布。':String(e)}finally{if(g===generation){busy.value=false;ready.value=true}}}

watch([path,page,filterYear,filterType,filterMode,previewRevision],()=>{menu.value=false;lightbox.value=null;void load()},{immediate:true})
async function logout(){await request('/auth/logout',{method:'POST'});await router.replace('/login')}
function showPhoto(photo:any){lightbox.value=photo}
const dialog=ref<HTMLDialogElement|null>(null)
watch(lightbox,async(v)=>{if(v){const {nextTick}=await import('vue');await nextTick();dialog.value?.showModal()}else if(dialog.value?.open)dialog.value.close()})
onUnmounted(()=>{generation++})
function plain(value:string){return value.replace(/<[^>]*>/g,'').replace(/[#*>`_]/g,'').trim()}
</script>
<template><div class="blog lj-theme" v-bind="appearanceAttrs(appearance)" :data-mode="dark?'dark':'light'" :data-custom="customKeys(appearance,dark?'dark':'light')" :style="colorStyle(appearance,dark?'dark':'light')" :class="{'blog-embedded':embedded}">
<a class="skip-link" href="#reading-content">跳到内容</a>
<p v-if="!ready" class="blog-startup" role="status">正在翻开私人生活档案…</p><div class="blog-wrap" :class="{'blog-initializing':!ready}"><header class="blog-header" @keydown.esc.stop.prevent="closeMenu"><a class="blog-brand" href="/" @click="go('/',$event)"><span class="blog-kicker">PRIVATE LIFE ARCHIVE</span><strong>{{site.title}}</strong><small>Life Journal v{{VERSION}}</small><small>{{label('site.subtitle','')}}</small></a><button ref="menuButton" class="mobile-menu" :aria-expanded="menu" aria-controls="blog-navigation" @click="menu=!menu">{{menu?'关闭菜单':'打开菜单'}}</button>
<nav id="blog-navigation" class="blog-nav" :class="{open:menu}" aria-label="私人Blog导航"><a href="/" :aria-current="path==='/'?'page':undefined" @click="go('/',$event)">{{label('nav.home','首页')}}</a><div v-for="n in roots" :key="n.id" class="nav-group"><a :href="navPath(n,site.sections)" :aria-current="activeNav(n)?'page':undefined" @click="go(navPath(n,site.sections),$event)">{{n.name}}</a><button v-if="children(n.id).length" class="nav-expand" :aria-expanded="expanded===n.id" :aria-label="'展开'+n.name+'子菜单'" @click="expanded=expanded===n.id?'':n.id">⌄</button><div v-if="expanded===n.id" class="nav-children"><a v-for="c in children(n.id)" :key="c.id" :href="navPath(c,site.sections)" @click="go(navPath(c,site.sections),$event)">{{c.name}}</a></div></div><a href="/archive" @click="go('/archive',$event)">{{label('nav.archive','生活归档')}}</a><a href="/timeline" @click="go('/timeline',$event)">{{label('nav.timeline','生活时间线')}}</a><a :href="'/year-review/'+new Date().getFullYear()" @click="go('/year-review/'+new Date().getFullYear(),$event)">{{label('nav.year','年度回顾')}}</a><a href="/sections" @click="go('/sections',$event)">{{label('nav.sections','所有栏目')}}</a><a v-if="admin&&!embedded" href="/drafts" @click="go('/drafts',$event)">我的草稿</a><a v-if="!embedded" href="/food" @click="go('/food',$event)">美食足迹</a><a v-if="admin&&!embedded" href="/write" @click="go('/write',$event)">写下新故事</a><a v-if="admin&&!embedded" href="/admin/site" @click="go('/admin/site',$event)">{{label('admin.site','管理站点')}}</a><a v-if="admin&&!embedded" href="/admin/content" @click="go('/admin/content',$event)">{{label('admin.content','内容后台')}}</a><button v-if="!embedded" class="blog-link" @click="logout">退出登录</button></nav></header><ThemeOrnament/>
<main id="reading-content" class="blog-main"><p v-if="busy" class="blog-empty" role="status">正在翻开这一页…</p><section v-else-if="error||!known" class="blog-empty"><span class="blog-kicker">PRIVATE JOURNAL</span><h1>{{path==='/forbidden'?'没有访问权限':known?'这一页暂时留白':'404 · 没有找到这一页'}}</h1><p>{{error||'可以从首页继续探索。'}}</p><a href="/" @click="go('/',$event)">返回首页</a></section>
<ArchivePage v-else-if="path==='/archive'" /><LifeFeed v-else-if="feed" :data="feed" :annual="path.startsWith('/year-review/')" :year="filterYear" :type-id="filterType" :record-mode="filterMode" :page="page" @navigate="go($event)" /><template v-else-if="home"><section v-for="m in home.modules" :key="m.id" class="home-module" :class="['module-'+m.kind,'layout-'+m.layout]">
<template v-if="m.kind==='hero'"><span class="blog-kicker">A LIFE, WELL REMEMBERED</span><h1>{{m.id===home.modules.find(x=>x.kind==='hero')?.id?label('home.welcome',m.title||home.title):(m.title||home.title)}}</h1><p>{{m.id===home.modules.find(x=>x.kind==='hero')?.id?label('home.introduction',m.text||home.description):(m.text||home.description)}}</p><a class="blog-cta" href="/stories" @click="go('/stories',$event)">翻阅所有故事 <span>↗</span></a></template>
<template v-else-if="m.kind==='anniversary_calendar'"><h2>{{m.title||'重要日子'}}</h2><article v-for="e in m.events||[]" :key="e.id+e.date" class="anniversary-home"><a :href="'/calendar?event='+e.id">{{e.name}}</a> · {{e.date}} <span v-if="e.days_left===0">今天</span><span v-else-if="m.show_countdown!==false">还有 {{e.days_left}} 天</span><span v-if="m.show_years!==false"> · {{e.years}} 周年</span></article><a href="/calendar">查看万年历与历史回忆 ↗</a></template><template v-else-if="m.kind==='text'"><h2 v-if="m.title">{{m.title}}</h2><div class="blog-prose" v-html="renderMarkdown(m.text)"></div></template>
<template v-else><div class="module-heading"><h2>{{m.title}}</h2><span class="blog-kicker">COLLECTED MOMENTS</span></div><div v-if="m.items?.length" class="story-grid"><a v-for="r in m.items" :key="r.id" class="story-card" :class="{'gallery-card':m.kind==='gallery','text-story':!r.cover}" :href="'/posts/'+r.id" @click="post(r.id,$event)"><PrivatePreview v-if="r.cover" :id="r.cover.id" :alt="r.cover.alt" /><div class="story-copy"><span class="story-date">{{r.display_date}} · {{r.record_mode_name||r.type_name}}</span><h3>{{r.title}}</h3><p v-if="m.kind!=='gallery'">{{plain(r.excerpt)}}</p><span class="read-story">阅读故事 ↗</span></div></a></div><p v-else class="blog-empty">故事正在慢慢积累。这里会留下值得记住的片刻。</p></template>
</section><section v-if="!home.modules.length" class="blog-empty"><h1>{{home.title}}</h1><p>{{home.description}}</p><p>在留白中，等一个新的故事。</p></section></template>
<template v-else-if="article"><a v-if="admin&&!embedded" :href="'/write/'+article.id" @click="go('/write/'+article.id,$event)">编辑文章</a><nav class="reading-back" aria-label="文章路径"><a href="/" @click="go('/',$event)">{{label('nav.home','首页')}}</a><span> / </span><a v-if="article.sections.length" :href="'/sections/'+article.sections[0].slug" @click="go('/sections/'+article.sections[0].slug,$event)">{{article.sections[0].name}}</a><a v-else href="/stories" @click="go('/stories',$event)">所有故事</a></nav><ArticleReader :context="{title:article.title,type:article.type_name,date:article.display_date}" :key="path" :embedded="embedded" :hash="embedded?'':String(route.hash)" @anchor="router.push({path:route.path,query:route.query,hash:'#'+$event})"><p v-if="article.template&&path.startsWith('/preview/')" class="preview-warning">Admin草稿预览 · 普通读者无法访问未发布记录</p><nav v-if="article.tags?.length" class="tag-pills article-tags" aria-label="文章标签"><a v-for="t in article.tags" :key="t.id" :href="'/archive?tag='+t.id" @click="go('/archive?tag='+t.id,$event)">#{{t.name}}</a></nav><TemplateRenderer v-if="article.template" :article="article" :config="article.template.config" @navigate="go($event)" /><template v-else><header class="article-heading"><span class="blog-kicker">{{article.record_mode_name||article.type_name}} · {{article.display_date}}</span><p v-if="path.startsWith('/preview/')" class="preview-warning">Admin草稿预览 · 普通读者无法访问未发布记录</p><h1>{{article.title}}</h1><div class="article-sections"><a v-for="s in article.sections" :key="s.id" :href="'/sections/'+s.slug" @click="go('/sections/'+s.slug,$event)">{{s.name}}</a></div></header><figure v-if="article.cover" class="article-cover"><button class="photo-button" aria-label="放大封面图片" @click="showPhoto(article.media.find((m:any)=>m.id===article.cover.id))"><PrivatePreview variant="preview" :eager="true" :id="article.cover.id" :alt="article.cover.alt" :width="article.cover.width" :height="article.cover.height" /></button></figure><ArticleBody :source="article.body" :format="article.body_format" :namespace="'post-'+article.id" />
<dl class="reading-fields"><template v-for="f in article.fields" :key="f.id"><div v-if="fieldDisplay(f,article.values[f.id])"><dt>{{f.name}}</dt><dd v-if="f.kind==='markdown'" class="blog-prose" v-html="renderMarkdown(String(article.values[f.id]))"></dd><dd v-else>{{fieldDisplay(f,article.values[f.id])}}</dd></div></template></dl>
<section v-if="article.media.length" class="article-gallery"><h2>影像片刻</h2><PhotoGallery :photos="article.media" :notes="article.life?.photos||[]" :places="article.places" layout="masonry" group-by="manual"/></section>
<section v-if="article.links.length" class="related-stories"><h2>沿着故事继续走</h2><a v-for="r in article.links" :key="r.id+r.label" :href="'/posts/'+r.id" @click="post(r.id,$event)"><span>{{r.label}}</span><strong>{{r.title}} ↗</strong></a></section><section v-if="article.places.length" class="reading-places"><h2>故事中的地点</h2><div v-for="p in article.places" :key="p.id"><h3>{{p.name}}</h3><p>{{[p.country,p.region,p.city,p.address].filter(Boolean).join(' · ')}}</p><p>{{p.category}}</p><p class="plain-value">{{p.notes}}</p><small v-if="p.latitude!==null">{{p.latitude}}, {{p.longitude}}</small></div></section><template v-if="article.article?.travel_enabled!==false&&article.life?.activities?.length"><details><summary>行程整理与历史活动</summary><TripView :article="article" :selected="selectedPlace" @select="selectedPlace=$event"/></details><PlaceMap :article="article" :selected="selectedPlace" @select="selectedPlace=$event"/></template></template></ArticleReader><AdjacentPosts v-if="neighbors&&!embedded&&!path.startsWith('/preview/')" :data="neighbors" @navigate="go($event)" /></template>
<template v-else-if="path==='/sections'"><header class="section-heading"><span class="blog-kicker">CHAPTERS OF LIFE</span><h1>{{label('page.sections','所有栏目')}}</h1><p>每个栏目，都是生活的一个切面。</p></header><div class="story-grid sections-grid"><a v-for="s in site.sections" :key="s.id" class="story-card" :href="'/sections/'+s.slug" @click="go('/sections/'+s.slug,$event)"><PrivatePreview v-if="s.cover_id" :id="s.cover_id" :alt="s.name" /><div class="story-copy"><h2>{{s.name}}</h2><p>{{s.description}}</p></div></a></div><p v-if="!site.sections.length" class="blog-empty">栏目尚未建立。生活的章节，留待慢慢书写。</p></template>
<template v-else><header class="section-heading"><span class="blog-kicker">COLLECTED STORIES</span><h1>{{section?.name||label('page.stories','所有故事')}}</h1><p>{{section?.description||'把日常里的光，留在这里。'}}</p><PrivatePreview v-if="section?.cover_id" :id="section.cover_id" :alt="section.name" /></header><div class="story-grid" :class="'layout-'+(section?.layout||'grid2')"><a v-for="r in items" :key="r.id" :href="'/posts/'+r.id" class="story-card" :class="{'text-story':!r.cover}" @click="post(r.id,$event)"><PrivatePreview v-if="r.cover" :id="r.cover.id" :alt="r.cover.alt" /><div class="story-copy"><span class="story-date">{{r.display_date}} · {{r.record_mode_name||r.type_name}}</span><h2>{{r.title}}</h2><p>{{plain(r.excerpt)}}</p></div></a></div><p v-if="!items.length" class="blog-empty">这个章节还在等待第一个故事。</p><nav class="blog-pagination" aria-label="文章分页"><button :disabled="page<=1" @click="go(path+'?page='+(page-1))">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(total/12))}}</span><button :disabled="page*12>=total" @click="go(path+'?page='+(page+1))">下一页</button></nav></template>
</main><footer class="blog-footer"><a href="/about" @click="go('/about',$event)">关于本站</a><strong>{{site.title}}</strong><small>Life Journal v{{VERSION}}</small><small>{{label('site.subtitle','')}}</small><span>私人生活档案 · 只向已登录的你开放</span><a v-if="!embedded" href="/food" @click="go('/food',$event)">美食足迹</a><a v-if="admin&&!embedded" href="/write" @click="go('/write',$event)">写下新故事</a><a v-if="admin&&!embedded" href="/admin/site" @click="go('/admin/site',$event)">编辑这本生活杂志 ↗</a><p>{{label('footer.description','')}}</p><small>{{label('footer.copyright','Life Journal · 私人生活档案')}}</small></footer></div>
<dialog ref="dialog" class="lightbox" aria-label="图片放大预览" @close="lightbox=null" @click="($event.target===dialog)&&(lightbox=null)"><template v-if="lightbox"><button class="lightbox-close" autofocus @click="lightbox=null">关闭图片</button><PrivatePreview variant="preview" :eager="true" :id="lightbox.id" :alt="lightbox.alt" /><p>{{lightbox.caption||lightbox.title}}</p></template></dialog></div></template>
